test('async: the same shielding reaches bad-toString errors nested under cause, arrays and Map entries', async () => {
  const workflow = {
    id: 'tostring-nested-errors',
    entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'form-one' },
      { id: 'form-one', type: 'form', next: 'act', schema: { fields: [
        { path: 'failure.message.toString', type: 'string', default: 'outer' },
        // The inner Error sits only behind the non-enumerable cause link.
        { path: 'failure.cause.inner.message.toString', type: 'string', default: 'inner' },
        // A Map value reached by an own plain-object field.
        { path: 'bag.errors.0.message.toString', type: 'string', default: 'mapped' },
      ] } },
      { id: 'act', type: 'action', operation: 'op', next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  const inner = new Error('inner-real');
  const failure = new Error('outer-real', { cause: { inner } });
  const mapped = new Error('mapped-real');
  const input = { failure, bag: { errors: [mapped] } };

  const result = await executeWorkflowAsync(workflow, input, {
    op: (received) => {
      assert.ok(received.failure instanceof Error);
      assert.equal(received.failure.message.toString, 'outer');
      assert.ok(received.failure.cause.inner instanceof Error);
      assert.equal(received.failure.cause.inner.message, 'inner-real',
        'a string message is never touched by the shield');
      assert.equal(received.failure.cause.inner.message.toString, 'inner');
      assert.ok(received.bag.errors[0] instanceof Error);
      assert.equal(received.bag.errors[0].message.toString, 'mapped');
      return 'A';
    },
  });
  assert.equal(result.status, 'completed');
  // Live input and caller objects kept their form-written values.
  assert.equal(result.context.input.failure.message.toString, 'outer');
  assert.equal(result.context.input.failure.cause.inner.message.toString, 'inner');
  assert.equal(result.context.input.bag.errors[0].message.toString, 'mapped');
  assert.equal(failure.cause.inner.message.toString, 'inner');
});

