input.command:
node -e "
import('./src/engine.js').then(async ({ executeWorkflow, executeWorkflowAsync }) => {
  // 1) Sync entry: legacy message action, condition reads the toString field off live input.
  const syncWf = {
    id: 'sync-tostring', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'form-one' },
      { id: 'form-one', type: 'form', next: 'gate', schema: { fields: [
        { path: 'failure.message.toString', type: 'string', default: 'web' },
        { path: 'failure.message.label', type: 'string', default: 'web' },
      ] } },
      { id: 'gate', type: 'condition', then: 'act', else: 'missed',
        condition: { field: 'failure.message.toString', operator: 'eq', value: 'web' } },
      { id: 'act', type: 'action', message: 'go', next: 'done' },
      { id: 'done', type: 'end', result: 'finished' },
      { id: 'missed', type: 'end', result: 'miss' },
    ],
  };
  const s = executeWorkflow(syncWf, { failure: new Error() });
  console.log('sync:', s.status, s.result);

  // 2) Failed later form rolls toString message back; earlier compensation
  //    snapshot (captured before the failed form) compensates with its own input.
  const wf = {
    id: 'rollback-comp', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'form-one' },
      { id: 'form-one', type: 'form', next: 'act', schema: { fields: [
        { path: 'failure.message.toString', type: 'string', default: 'web' },
      ] } },
      { id: 'act', type: 'action', operation: 'op', compensation: { operation: 'undo' }, next: 'form-two' },
      { id: 'form-two', type: 'form', next: 'end', schema: { fields: [
        { path: 'failure.message.temp', type: 'string', default: 'T' },
        { path: 'missing.required', type: 'string', required: true },
      ] } },
      { id: 'end', type: 'end', result: 'done' },
    ],
  };
  const callerFailure = new Error();
  const compSeen = [];
  const r = await executeWorkflowAsync(wf, { failure: callerFailure }, {
    op: (i) => { i.failure.message.toString; return 'tx'; },
    undo: (i) => { compSeen.push(i.failure.message); return 'released'; },
  });
  console.log('async:', r.status, '| comp input msg:', JSON.stringify(compSeen[0]),
    '| live own temp?', Object.hasOwn(r.context.input.failure.message, 'temp'),
    '| caller own message?', Object.hasOwn(callerFailure, 'message'));
});
"

